import java.nio.file.*;import java.nio.file.attribute.*;public class TreeReport{public static void main(String[]x)throws Exception{Path dir=Path.of(".");StringBuilder b=new StringBuilder();try(var s=Files.walk(dir,2)){s.filter(Files::isRegularFile).forEach(p->{try{BasicFileAttributes a=Files.readAttributes(p,BasicFileAttributes.class);b.append(p).append(" | ").append(a.size()).append(" | ").append(a.lastModifiedTime()).append('\n');}catch(Exception e){}});}Files.writeString(Path.of("tree-report.txt"),b.toString());System.out.println("Wrote tree-report.txt");}}
